-- Case date-modified-raw: PhotoInfo.DateModifiedRaw (ZMODIFICATIONDATE) apart from DateModified
-- (ZADJUSTMENTTIMESTAMP).
-- Changes: the asset marked mig:date-modified-raw-value gets ZMODIFICATIONDATE 694224000
-- (2023-01-01T00:00:00Z) and ZADJUSTMENTTIMESTAMP 694310400 (2023-01-02T00:00:00Z); the asset marked
-- mig:date-modified-raw-null gets ZMODIFICATIONDATE NULL.
-- Expects: value: DateModifiedRaw 2023-01-01T00:00:00Z and DateModified 2023-01-02T00:00:00Z;
-- null: DateModifiedRaw nil.

UPDATE ZADDITIONALASSETATTRIBUTES SET ZTITLE = 'mig:date-modified-raw-value'
WHERE Z_PK = (SELECT x.Z_PK FROM ZADDITIONALASSETATTRIBUTES x JOIN ZASSET a ON a.Z_PK = x.ZASSET
              WHERE (x.ZTITLE IS NULL OR x.ZTITLE NOT LIKE 'mig:%')
                AND a.ZTRASHEDSTATE = 0 AND a.ZAVALANCHEUUID IS NULL
              ORDER BY a.ZUUID LIMIT 1);

UPDATE ZASSET SET ZMODIFICATIONDATE = 694224000, ZADJUSTMENTTIMESTAMP = 694310400
WHERE Z_PK = (SELECT ZASSET FROM ZADDITIONALASSETATTRIBUTES WHERE ZTITLE = 'mig:date-modified-raw-value');

UPDATE ZADDITIONALASSETATTRIBUTES SET ZTITLE = 'mig:date-modified-raw-null'
WHERE Z_PK = (SELECT x.Z_PK FROM ZADDITIONALASSETATTRIBUTES x JOIN ZASSET a ON a.Z_PK = x.ZASSET
              WHERE (x.ZTITLE IS NULL OR x.ZTITLE NOT LIKE 'mig:%')
                AND a.ZTRASHEDSTATE = 0 AND a.ZAVALANCHEUUID IS NULL
              ORDER BY a.ZUUID LIMIT 1);

UPDATE ZASSET SET ZMODIFICATIONDATE = NULL
WHERE Z_PK = (SELECT ZASSET FROM ZADDITIONALASSETATTRIBUTES WHERE ZTITLE = 'mig:date-modified-raw-null');
